'use strict';

// MODULES //

var isFunction = require( '@stdlib/assert/is-function' );
var isArray = require( '@stdlib/assert/is-array' );
var isObject = require( '@stdlib/assert/is-object' );
var copy = require( '@stdlib/utils/copy' );


// MAIN //

/**
* Serializes a list of private instance properties from a class instance to a JSON object.
*
* @param {Object} obj - input instance
* @param {Array<string>} properties - properties to serialize
* @returns {Object} JSON object
*/
function toJSON( obj, properties ) {
	var out;
	var tmp;
	var v;
	var o;
	var k;
	var i;
	var j;

	out = {};
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		v = obj[ '_'+k ];
		if ( v === void 0 ) {
			continue;
		}
		if ( isArray( v ) ) {
			tmp = [];
			for ( j = 0; j < v.length; j++ ) {
				o = v[ j ];
				if ( o && isFunction( o.toJSON ) ) {
					tmp.push( o.toJSON() );
				} else if ( isObject( o ) ) {
					tmp.push( copy( o ) );
				} else {
					tmp.push( o );
				}
			}
			out[ k ] = tmp;
		} else if ( v && isFunction( v.toJSON ) ) {
			out[ k ] = v.toJSON();
		} else if ( isObject( v ) ) {
			out[ k ] = copy( v );
		} else {
			out[ k ] = v;
		}
	}
	return out;
}


// EXPORTS //

module.exports = toJSON;
